import { useEffect, useMemo, useState } from 'react';
import { GeoJSON, Marker, useMap } from 'react-leaflet';
import * as L from 'leaflet';
import indiaStates from '../../utils/basemap/indiaStates';
import worldCountries from '../../utils/basemap/worldCountries';

/**
 * Local, fully self-contained basemap.
 *
 * Renders bundled GeoJSON (Natural Earth, public domain) instead of fetching
 * raster tiles from an external map provider. Nothing leaves the deployment:
 * no API key, no tile quota, no third-party uptime dependency, no WebGL.
 * The assets are generated by `scripts/build-local-basemap.mjs`.
 *
 * Layer order matters — this component is the first child of <MapContainer>, so
 * its polygons sit underneath the crime heatmap, attack vectors and markers.
 *
 * Labels follow the zoom level: country names while the world is in view, then
 * the 36 Indian states/UTs once the map is close enough to read them.
 */

const ATTRIBUTION =
  'Boundaries: <a href="https://www.naturalearthdata.com/" target="_blank" rel="noopener">Natural Earth</a> (public domain)';

// Labels start at the India-locked minimum zoom and stop before city level,
// where street/POI detail would normally take over.
const LABEL_MIN_ZOOM = 6;
const LABEL_MAX_ZOOM = 9;

// Small union territories collide with their neighbours' labels at country
// zoom, so they only get a label once the user zooms in.
const SMALL_REGIONS = new Set([
  'Chandigarh',
  'Delhi',
  'Puducherry',
  'Lakshadweep',
  'Andaman and Nicobar',
  'Dadra and Nagar Haveli and Daman and Diu',
]);
const SMALL_REGION_MIN_ZOOM = 7;

const SHORT_LABELS: Record<string, string> = {
  'Andaman and Nicobar': 'A & N Islands',
  'Dadra and Nagar Haveli and Daman and Diu': 'DNH & Daman-Diu',
  'Arunachal Pradesh': 'Arunachal',
  'Himachal Pradesh': 'Himachal',
  'Jammu and Kashmir': 'J & K',
};

const WORLD_STYLE: L.PathOptions = {
  color: '#1a2437',
  weight: 0.7,
  opacity: 0.9,
  fillColor: '#070d18',
  fillOpacity: 1,
  interactive: false,
};

const INDIA_STYLE: L.PathOptions = {
  color: '#2b3d5a',
  weight: 0.9,
  opacity: 0.85,
  fillColor: '#0d1829',
  fillOpacity: 1,
  interactive: false,
};

// Country names replace state names once the whole world is in view. Natural
// Earth's label rank decides how early a country earns its name: 2 is drawn with
// the entire world on screen, 5+ only after zooming in towards it.
const COUNTRY_LABEL_MAX_ZOOM = 5;

const SHORT_COUNTRY_LABELS: Record<string, string> = {
  'United States of America': 'United States',
  'United Arab Emirates': 'UAE',
  'Dem. Rep. Congo': 'DR Congo',
};

const labelIcons = new Map<string, L.DivIcon>();

function labelIcon(name: string): L.DivIcon {
  let icon = labelIcons.get(name);
  if (!icon) {
    icon = L.divIcon({
      className: 'basemap-label',
      html: `<span>${SHORT_LABELS[name] || name}</span>`,
      iconSize: [0, 0],
      iconAnchor: [0, 0],
    });
    labelIcons.set(name, icon);
  }
  return icon;
}

const countryLabelIcons = new Map<string, L.DivIcon>();

function countryLabelIcon(name: string): L.DivIcon {
  let icon = countryLabelIcons.get(name);
  if (!icon) {
    icon = L.divIcon({
      className: 'basemap-label basemap-label--country',
      html: `<span>${SHORT_COUNTRY_LABELS[name] || name}</span>`,
      iconSize: [0, 0],
      iconAnchor: [0, 0],
    });
    countryLabelIcons.set(name, icon);
  }
  return icon;
}

function StateLabels() {
  const map = useMap();
  const [zoom, setZoom] = useState(() => map.getZoom());

  useEffect(() => {
    const onZoomEnd = () => setZoom(map.getZoom());
    map.on('zoomend', onZoomEnd);
    return () => {
      map.off('zoomend', onZoomEnd);
    };
  }, [map]);

  const visible = useMemo(() => {
    if (zoom < LABEL_MIN_ZOOM || zoom > LABEL_MAX_ZOOM) return [];
    return indiaStates.features.filter(
      (feature) =>
        zoom >= SMALL_REGION_MIN_ZOOM || !SMALL_REGIONS.has(feature.properties.name),
    );
  }, [zoom]);

  if (visible.length === 0) return null;

  return (
    <>
      {visible.map((feature) => (
        <Marker
          key={feature.properties.name}
          position={feature.properties.label}
          icon={labelIcon(feature.properties.name)}
          interactive={false}
          keyboard={false}
        />
      ))}
    </>
  );
}

function CountryLabels() {
  const map = useMap();
  const [zoom, setZoom] = useState(() => map.getZoom());

  useEffect(() => {
    const onZoomEnd = () => setZoom(map.getZoom());
    map.on('zoomend', onZoomEnd);
    return () => {
      map.off('zoomend', onZoomEnd);
    };
  }, [map]);

  const visible = useMemo(() => {
    if (zoom > COUNTRY_LABEL_MAX_ZOOM) return [];
    return worldCountries.features.filter((feature) => {
      const rank = feature.properties.rank;
      // Rank 2 countries are labelled at every zoom the world fits in (the
      // fitted zoom can sit below 2 on tall or narrow map areas).
      const minZoom = rank <= 2 ? 0 : Math.min(rank, COUNTRY_LABEL_MAX_ZOOM);
      return zoom >= minZoom;
    });
  }, [zoom]);

  if (visible.length === 0) return null;

  return (
    <>
      {visible.map((feature) => (
        <Marker
          key={feature.properties.code}
          position={feature.properties.label}
          icon={countryLabelIcon(feature.properties.name)}
          interactive={false}
          keyboard={false}
        />
      ))}
    </>
  );
}

export default function LocalBasemap() {
  const map = useMap();

  // Credit the data source on the map itself (public-domain data, but the
  // attribution is still the right thing to show).
  useEffect(() => {
    const control = map.attributionControl;
    if (!control) return;
    control.addAttribution(ATTRIBUTION);
    return () => {
      control.removeAttribution(ATTRIBUTION);
    };
  }, [map]);

  return (
    <>
      {/* World: everything outside India is context — no borders detail. */}
      <GeoJSON data={worldCountries} style={WORLD_STYLE} />

      {/* India: all 36 states/UTs, the same geometry the crime overlay colors. */}
      <GeoJSON data={indiaStates} style={INDIA_STYLE} />

      <CountryLabels />
      <StateLabels />
    </>
  );
}
